import{_ as a,o as e,c as r,O as s}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"工程化落地","description":"相关笔记：04 框架技术栈 · 8. Spring AI、项目复盘：心理健康 AI 助手、OpenTelemetry 可观测性","frontmatter":{"description":"相关笔记：04 框架技术栈 · 8. Spring AI、项目复盘：心理健康 AI 助手、OpenTelemetry 可观测性","tags":["AI Agent","高并发","大模型","缓存"]},"headers":[],"relativePath":"backend/AI-Agent/07-工程化落地.md","filePath":"backend/AI-Agent/07-工程化落地.md","lastUpdated":1793245104000}'),d={name:"backend/AI-Agent/07-工程化落地.md"};function n(o,t,l,p,i,c){return e(),r("div",null,t[0]||(t[0]=[s(`<h1 id="工程化落地" tabindex="-1">工程化落地 <a class="header-anchor" href="#工程化落地" aria-label="Permalink to &quot;工程化落地&quot;">​</a></h1><blockquote><p>相关笔记：<a href="./../Java/04-java框架技术栈">04 框架技术栈 · 8. Spring AI</a>、<a href="./../Java/项目复盘-心理健康AI助手">项目复盘：心理健康 AI 助手</a>、<a href="./../../devops/OpenTelemetry可观测性">OpenTelemetry 可观测性</a></p></blockquote><blockquote><p>前面六篇讲「怎么让它聪明」，这篇讲「怎么让它因为不聪明也不出事」。<strong>面试里最值钱的一篇</strong> —— 能讲清成本、稳定性、可观测，说明你真上过线。</p></blockquote><h2 id="_1-分层架构" tabindex="-1">1. 分层架构 <a class="header-anchor" href="#_1-分层架构" aria-label="Permalink to &quot;1. 分层架构&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">接入层   HTTP/SSE 接口、鉴权、限流、审计</span></span>
<span class="line"><span style="color:#e1e4e8;">编排层   Prompt 组装 → 记忆 → RAG → 工具 → 输出校验</span></span>
<span class="line"><span style="color:#e1e4e8;">能力层   模型网关（多厂商路由/熔断/降级）、向量库、工具集</span></span>
<span class="line"><span style="color:#e1e4e8;">数据层   会话/消息、知识库、向量、用量账单、评测集</span></span>
<span class="line"><span style="color:#e1e4e8;">观测层   trace + token 统计 + 质量指标 + 告警</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">接入层   HTTP/SSE 接口、鉴权、限流、审计</span></span>
<span class="line"><span style="color:#24292e;">编排层   Prompt 组装 → 记忆 → RAG → 工具 → 输出校验</span></span>
<span class="line"><span style="color:#24292e;">能力层   模型网关（多厂商路由/熔断/降级）、向量库、工具集</span></span>
<span class="line"><span style="color:#24292e;">数据层   会话/消息、知识库、向量、用量账单、评测集</span></span>
<span class="line"><span style="color:#24292e;">观测层   trace + token 统计 + 质量指标 + 告警</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>分层的目的：<strong>换模型、换向量库、加一个模型厂商，只改一层</strong>。反例是把 <code>chatClient.call()</code> 散落在 20 个 Service 里，换模型要改一天。</p><h2 id="_2-模型网关-所有调用的唯一出口" tabindex="-1">2. 模型网关：所有调用的唯一出口 <a class="header-anchor" href="#_2-模型网关-所有调用的唯一出口" aria-label="Permalink to &quot;2. 模型网关：所有调用的唯一出口&quot;">​</a></h2><p>必须做网关的五个理由：</p><table><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td><strong>多厂商路由</strong></td><td>主备切换、按能力/成本分流</td></tr><tr><td><strong>熔断降级</strong></td><td>某厂商连续失败就切断，半开探测恢复</td></tr><tr><td><strong>配额与限流</strong></td><td>按用户/租户/全局三层</td></tr><tr><td><strong>统一日志</strong></td><td>每次调用记录 model/prompt 版本/token/耗时</td></tr><tr><td><strong>成本归因</strong></td><td>谁在花钱、花在哪个功能上</td></tr></tbody></table><h3 id="_2-1-三态熔断器" tabindex="-1">2.1 三态熔断器 <a class="header-anchor" href="#_2-1-三态熔断器" aria-label="Permalink to &quot;2.1 三态熔断器&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">CLOSED（正常放行） --失败率超阈值--&gt; OPEN（直接拒绝）</span></span>
<span class="line"><span style="color:#e1e4e8;">        ↑                                  │</span></span>
<span class="line"><span style="color:#e1e4e8;">        └──── HALF_OPEN（放少量探测） &lt;──── 冷却时间到</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">CLOSED（正常放行） --失败率超阈值--&gt; OPEN（直接拒绝）</span></span>
<span class="line"><span style="color:#24292e;">        ↑                                  │</span></span>
<span class="line"><span style="color:#24292e;">        └──── HALF_OPEN（放少量探测） &lt;──── 冷却时间到</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>参数经验：统计窗口 10s、最小请求数 20、失败率阈值 50%、OPEN 冷却 30s、HALF_OPEN 放行 3 个。</p><h3 id="_2-2-降级链" tabindex="-1">2.2 降级链 <a class="header-anchor" href="#_2-2-降级链" aria-label="Permalink to &quot;2.2 降级链&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">主力模型 → 重试 1 次 → 备用模型（另一厂商）→ 规则/模板回答 → 固定话术</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">主力模型 → 重试 1 次 → 备用模型（另一厂商）→ 规则/模板回答 → 固定话术</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>关键是<strong>每一层都有明确的触发条件和用户可见的表现</strong>，不能静默失败。</p><h2 id="_3-成本工程" tabindex="-1">3. 成本工程 <a class="header-anchor" href="#_3-成本工程" aria-label="Permalink to &quot;3. 成本工程&quot;">​</a></h2><table><thead><tr><th>手段</th><th>典型收益</th></tr></thead><tbody><tr><td><code>max_tokens</code> 限制输出</td><td>防跑飞，兜底</td></tr><tr><td>上下文瘦身（Top-K 片段）</td><td>输入 token 降一个数量级</td></tr><tr><td><strong>模型路由</strong>（简单问题走小模型）</td><td>成本降 50%～80%</td></tr><tr><td><strong>结果缓存</strong>（问题归一化后哈希）</td><td>高频问题零成本</td></tr><tr><td><strong>Prompt 缓存</strong>（厂商前缀缓存）</td><td>长系统提示词场景显著</td></tr><tr><td>流式 + 用户中断</td><td>省下未输出的 token</td></tr><tr><td>批处理（离线任务）</td><td>部分厂商有批量折扣</td></tr></tbody></table><p><strong>先把账算清</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">单次成本 = 输入token × 输入单价 + 输出token × 输出单价</span></span>
<span class="line"><span style="color:#e1e4e8;">日成本   = 日请求数 × 单次成本</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">单次成本 = 输入token × 输入单价 + 输出token × 输出单价</span></span>
<span class="line"><span style="color:#24292e;">日成本   = 日请求数 × 单次成本</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>一个带 3 段 RAG 的问答大约 2000～4000 输入 token + 300～800 输出 token。按单价一乘就知道量级，<strong>先算再优化</strong>。</p><h2 id="_4-性能-三个数决定体验" tabindex="-1">4. 性能：三个数决定体验 <a class="header-anchor" href="#_4-性能-三个数决定体验" aria-label="Permalink to &quot;4. 性能：三个数决定体验&quot;">​</a></h2><table><thead><tr><th>指标</th><th>含义</th><th>优化方向</th></tr></thead><tbody><tr><td><strong>TTFT</strong>（首 token 延迟）</td><td>用户点完到看到第一个字</td><td>缩短输入、prefill 前置、模型路由、边缘部署</td></tr><tr><td><strong>TPOT</strong>（每 token 时间）</td><td>出字速度</td><td>换更快的模型/推理引擎</td></tr><tr><td><strong>P95 总时长</strong></td><td>长回答的尾部延迟</td><td><code>max_tokens</code>、控制输出长度、流式</td></tr></tbody></table><p>工程要点：</p><ul><li><strong>一定要流式</strong>（SSE），否则用户白屏等待；</li><li>流式占线程 → 用 WebFlux/Netty 或异步 Servlet，别用 Tomcat 线程硬扛（详见 <a href="./../Java/项目复盘-心理健康AI助手">项目复盘</a> 的踩坑 10.6）；</li><li>网关/代理要关缓冲（<code>proxy_buffering off</code>）、加长超时、发心跳。</li></ul><h2 id="_5-稳定性四件套" tabindex="-1">5. 稳定性四件套 <a class="header-anchor" href="#_5-稳定性四件套" aria-label="Permalink to &quot;5. 稳定性四件套&quot;">​</a></h2><table><thead><tr><th>件</th><th>要点</th></tr></thead><tbody><tr><td><strong>超时</strong></td><td>首 token 超时（如 10s）+ 总超时（如 120s），<strong>别用默认值</strong></td></tr><tr><td><strong>重试</strong></td><td>只重试幂等请求；指数退避 + 抖动；最多 1～2 次</td></tr><tr><td><strong>幂等</strong></td><td>有副作用的操作（下单）带幂等键，重试不重复执行</td></tr><tr><td><strong>限流</strong></td><td>用户级（防刷）+ 租户级（防挤占）+ 全局级（防打爆）</td></tr></tbody></table><p>限流算法按场景选：令牌桶（允许突发）、漏桶（平滑）、滑动窗口（精确）。</p><h2 id="_6-可观测-四个必看指标" tabindex="-1">6. 可观测：四个必看指标 <a class="header-anchor" href="#_6-可观测-四个必看指标" aria-label="Permalink to &quot;6. 可观测：四个必看指标&quot;">​</a></h2><table><thead><tr><th>指标</th><th>为什么</th></tr></thead><tbody><tr><td><strong>TTFT / 总耗时 P95</strong></td><td>用户体验的主指标</td></tr><tr><td><strong>token 消耗</strong>（输入/输出分开）</td><td>成本</td></tr><tr><td><strong>失败率 / 降级率</strong></td><td>稳定性</td></tr><tr><td><strong>检索命中率 / 空召回率</strong></td><td>RAG 效果（有 RAG 才需要）</td></tr></tbody></table><p>日志必须能串起来：<code>traceId → prompt 版本 → 检索到的 docId → 模型 → token → 耗时 → 是否降级</code>。</p><p>出了问题第一句话应该是「把 traceId 给我」，而不是「我本地复现一下」。</p><h2 id="_7-评测与发布-别靠感觉上线" tabindex="-1">7. 评测与发布：别靠感觉上线 <a class="header-anchor" href="#_7-评测与发布-别靠感觉上线" aria-label="Permalink to &quot;7. 评测与发布：别靠感觉上线&quot;">​</a></h2><table><thead><tr><th>环节</th><th>做法</th></tr></thead><tbody><tr><td><strong>评测集</strong></td><td>50～200 条真实问题 + 期望输出/评分规则，覆盖主流程 + 边界 + 拒答</td></tr><tr><td><strong>离线回归</strong></td><td>每次改 Prompt/模型/检索参数都跑一遍，看指标不能倒退</td></tr><tr><td><strong>灰度</strong></td><td>按用户/流量比例切新版，观察 24h</td></tr><tr><td><strong>A/B</strong></td><td>关键改动做对照，看业务指标（不是只看模型指标）</td></tr><tr><td><strong>回滚</strong></td><td>Prompt、模型、检索参数都要能一键切回</td></tr></tbody></table><p><strong>发布清单</strong>（很实用）：</p><ul><li>[ ] 评测集指标不倒退</li><li>[ ] 成本增量在预算内</li><li>[ ] 降级链路演练过（手动切断主力模型能正常兜底）</li><li>[ ] 日志能定位到本次改动的版本号</li><li>[ ] 灰度人群和回滚方式明确</li></ul><h2 id="_8-安全与合规" tabindex="-1">8. 安全与合规 <a class="header-anchor" href="#_8-安全与合规" aria-label="Permalink to &quot;8. 安全与合规&quot;">​</a></h2><table><thead><tr><th>项</th><th>做法</th></tr></thead><tbody><tr><td>数据脱敏</td><td>手机号/身份证/银行卡在进模型前替换占位符</td></tr><tr><td>数据出境</td><td>确认模型服务的部署地域与合规要求</td></tr><tr><td>内容安全</td><td>输入输出双向过滤，命中走固定话术</td></tr><tr><td>越权</td><td>工具内部鉴权，不信模型参数</td></tr><tr><td>留痕</td><td>完整的请求/响应/工具调用记录，可审计</td></tr><tr><td>用户权利</td><td>支持删除会话与记忆</td></tr></tbody></table><h2 id="_9-团队协作-把-ai-当软件工程做" tabindex="-1">9. 团队协作：把 AI 当软件工程做 <a class="header-anchor" href="#_9-团队协作-把-ai-当软件工程做" aria-label="Permalink to &quot;9. 团队协作：把 AI 当软件工程做&quot;">​</a></h2><table><thead><tr><th>资产</th><th>管理方式</th></tr></thead><tbody><tr><td>Prompt</td><td>独立目录 + 版本号 + review + 变更记录</td></tr><tr><td>评测集</td><td>版本化，和 Prompt 版本对应</td></tr><tr><td>标注规范</td><td>写清「什么算好答案」，否则标注不一致</td></tr><tr><td>失败样本库</td><td>线上 badcase 持续回流，作为下一轮评测集</td></tr><tr><td>上线记录</td><td>每次变更记「改了什么、为什么、指标变化」</td></tr></tbody></table><blockquote><p>这条最容易被忽略：<strong>AI 项目的技术债主要是「不可复现」</strong> —— 换个人跑同样的输入得到不同结果，还没人知道当时用的是哪个 Prompt 版本。</p></blockquote><h2 id="_10-面试怎么讲-把这七篇串成一段" tabindex="-1">10. 面试怎么讲（把这七篇串成一段） <a class="header-anchor" href="#_10-面试怎么讲-把这七篇串成一段" aria-label="Permalink to &quot;10. 面试怎么讲（把这七篇串成一段）&quot;">​</a></h2><blockquote><p>「我做的是一条可控的 AI 链路：模型侧做网关，多厂商 + 三态熔断 + 降级到固定话术；Prompt 进版本库，配 50 条评测集做回归；RAG 用混合检索 + Rerank，只看 Recall@5 和忠实度这两个指标；上下文做了滑动窗口 + 摘要；成本上建了用量表，按用户和模型归因，再用模型路由把简单请求切到小模型；稳定性上超时/重试/幂等/限流四件套齐全，SSE 关掉 Nginx 缓冲、异常不交给全局处理器。上线前跑评测集，灰度 24 小时再放量。」</p></blockquote><p>这段话里几乎每个短语都能被追问，而追问的深度刚好由前六篇撑着。</p><h2 id="_11-速查表" tabindex="-1">11. 速查表 <a class="header-anchor" href="#_11-速查表" aria-label="Permalink to &quot;11. 速查表&quot;">​</a></h2><table><thead><tr><th>问题</th><th>一句话</th></tr></thead><tbody><tr><td>为什么要模型网关</td><td>多厂商路由、熔断、配额、统一日志、成本归因</td></tr><tr><td>三态熔断</td><td>CLOSED / OPEN / HALF_OPEN，半开探测恢复</td></tr><tr><td>成本怎么砍</td><td>max_tokens + 上下文瘦身 + 模型路由 + 缓存 + 配额</td></tr><tr><td>TTFT 怎么优化</td><td>砍输入、模型路由、流式、边缘部署</td></tr><tr><td>稳定性四件套</td><td>超时、重试（幂等）、幂等键、三层限流</td></tr><tr><td>必看指标</td><td>TTFT P95、token 消耗、失败/降级率、空召回率</td></tr><tr><td>上线流程</td><td>评测集回归 → 灰度 → A/B → 可回滚</td></tr><tr><td>最容易被忽略</td><td>Prompt 版本管理，出事时不知道用的哪版</td></tr><tr><td>安全底线</td><td>工具内部鉴权、输入输出过滤、全量留痕、可删除</td></tr></tbody></table>`,45)]))}const g=a(d,[["render",n]]);export{b as __pageData,g as default};
